// One player: a line of players.txt (chapters 3 and 4)
class Player
{
    private string username;
    private string password;
    private string avatar;
    private string joined;

// An empty player: the register form fills it in, rule by rule
public Player()
{
    username = "";
    password = "";
    avatar = "";
    joined = DateTime.Now.ToString("dd/MM/yyyy");
}

// A player read from players.txt: the rules are skipped
public Player(string username, string password, string avatar,
    string joined)
{
    this.username = username;
    this.password = password;
    this.avatar = avatar;
    this.joined = joined;
}

// The username
public string Username
{
    get { return username; }
    set { username = value; }
}

// The password
public string Password
{
    get { return password; }
    set { password = value; }
}

// The avatar's file name
public string Avatar
{
    get { return avatar; }
    set { avatar = value; }
}

// The date the player joined, like 02/09/2026
public string Joined
{
    get { return joined; }
    set { joined = value; }
}

// The player as one line of players.txt
public override string ToString()
{
    return username + "|" + password + "|" + avatar + "|" + joined;
}

// Reads and adds to players.txt (chapters 3 and 4)
static class PlayerFile
{
    // Reads every player in players.txt into a list
    public static List<Player> LoadAll()
    {
        List<Player> players = new List<Player>();
        string path = Files.Data("players.txt");
        if (!File.Exists(path)) return players;   // no file: no players
        StreamReader reader = new StreamReader(path);
        while (!reader.EndOfStream)
        {
            string line = reader.ReadLine();
            string[] parts = line.Split('|');
            if (parts.Length != 4) continue;      // skip a broken line
            players.Add(new Player(parts[0], parts[1], parts[2],
                parts[3]));
        }
        reader.Close();
        return players;
    }

// True when a player has this username, in any capitals
public static bool Exists(string username)
{
    List<Player> players = LoadAll();
    foreach (Player p in players)
    {
        if (p.Username.ToLower() == username.ToLower()) return true;
    }
    return false;
}

// Adds a new player to the end of players.txt
public static void Add(Player p)
{
    StreamWriter writer = new StreamWriter(Files.Data("players.txt"),
        true);                                // true: add to the end
    writer.WriteLine(p.ToString());
    writer.Close();
}

private void btnTest_Click(object sender, EventArgs e)
{
    Player p = new Player();
    p.Username = "testClimber";
    p.Password = "rope2026";
    p.Avatar = "avatar-fox.png";
    if (PlayerFile.Exists(p.Username))
    {
        MessageBox.Show(p.Username + " is already in players.txt.");
    }
    else
    {
        PlayerFile.Add(p);
        MessageBox.Show("Added: " + p.ToString());
    }
    List<Player> players = PlayerFile.LoadAll();
    MessageBox.Show("players.txt holds " + players.Count + " players.");
}
